///|
fn repository_slug(repository : String) -> String raise {
  let name = repository.trim_end(chars="/").split("/").to_array().last().unwrap()
    .split(":").to_array().last().unwrap().strip_suffix(".git").unwrap_or(name).to_lower()
  let slug = StringBuilder()
  let mut separator = false
  for c in name {
    if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') {
      if separator && slug.length() > 0 { slug.write_string("-") }
      slug.write_char(c)
      separator = false
    } else {
      separator = true
    }
  }
  let slug = slug.to_string()
  guard slug != "" else { raise AdapterError("Repository URL has no usable name") }
  slug
}

///|
fn workspace_name(slug : String) -> String raise {
  let alphabet = "REDACTED"
  for _ = 0; _ < 32; _ = _ + 1 {
    guard @env.rand(3) is Some(bytes) else {
      raise AdapterError("Workspace naming requires platform randomness")
    }
    if bytes[1].to_int() >= 252 || bytes[2].to_int() >= 252 { continue }
    let animal = workspace_animals[bytes[0].to_int() % workspace_animals.length()]
    let limit = 48 - animal.length() - 4
    let prefix = if slug.length() > limit { slug[0:limit].to_owned().trim_end(chars="-").to_owned() } else { slug }
    return prefix + "-" + animal + "-" + alphabet[bytes[1].to_int() % 36].to_string() + alphabet[bytes[2].to_int() % 36].to_string()
  }
  raise AdapterError("Unable to generate workspace name")
}

///|
async fn workspace_creation_lock() -> @fs.File {
  let directory = adapter_state_home()
  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
  let lock = @fs.open(directory + "/create.lock", mode=ReadWrite, create_mode=OpenOrCreate, permission=0o600)
  errdefer lock.close()
  @async.with_timeout(600000, async fn() {
    while !lock.try_lock(Exclusive) { @async.sleep(100) }
  })
  lock
}

///|
async fn select_workspace_name(state : Json, repository : String) -> Unit {
  let slug = repository_slug(repository)
  for attempt = 0; attempt < 64; attempt = attempt + 1 {
    let id = workspace_name(slug)
    set_field(state, "workspaceId", Json::string(id))
    let occupied = workspace(state) is Some(_)
    save_diagnostic("workspace-name", if occupied { "collision" } else { "selected" }, attempt=attempt + 1, source=IdentitySelection(slug, id))
    if !occupied { return }
  }
  raise AdapterError("Unable to reserve an unused workspace name")
}
