+fn volume_configuration_value(value : String, configured : Json, overrides : Json) -> String raise {
+  let output = StringBuilder()
+  let mut remaining = value
+  while remaining.split_once("${") is Some((prefix, expression)) {
+    guard !prefix.contains("$") && expression.split_once("}") is Some((variable, suffix)) &&
+      variable.length() > 0 && variable.iter().all(c => (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') else {
+      raise AdapterError("unsupported Devsy runtime variable expression")
+    }
+    let key = variable.to_owned()
+    let option = match field(overrides, key) {
+      Some(value) => value
+      None => match field(configured, key) {
+        Some(value) => value
+        None => raise AdapterError("unresolved Devsy runtime variable: " + key)
+      }
+    }
+    output.write_string(prefix.to_owned())
+    output.write_string(optional_text(option, "value"))
+    remaining = suffix.to_owned()
+  }
+  guard !remaining.contains("$") else {
+    raise AdapterError("unsupported Devsy runtime variable expression")
+  }
+  output.write_string(remaining)
+  output.to_string()
